/**
 * Lumina Cleaning Service — Loading Screen (final)
 * Real pre-rendered footage, not procedural canvas physics.
 *
 * Zero-flash start: the overlay paints SYNCHRONOUSLY, the instant this
 * script runs, using an inlined base64 copy of the clip's first frame
 * as an immediate placeholder background. No network request stands
 * between script-execution and something covering the hero section.
 *
 * Primary path: a single <video> element plays the WebM (VP9 + alpha)
 * file immediately and visibly. Alpha support is verified live against
 * that same playing element (only Chromium browsers actually composite
 * WebM alpha through <video> — Firefox/Safari render it fully opaque
 * regardless of the file's real alpha data). If unsupported, it swaps
 * to the WebP frame-sequence fallback below; if supported (the common
 * case), it just keeps playing — no redundant second video load.
 *
 * Fallback path: a WebP frame sequence, drawn frame-by-frame on canvas.
 * Static image alpha decoding is universally supported — this is the
 * guaranteed-safe path for Firefox, Safari, and anything else.
 */

(function () {
  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  if (sessionStorage.getItem('lumina-loaded')) return;
  sessionStorage.setItem('lumina-loaded', '1');

  const WEBM_SRC = 'Assets/video/loading-screen-lumina.webm';

  const FRAME_DIR    = 'Assets/images/loader-frames/';
  const FRAME_COUNT  = 79;   // frame_001.webp .. frame_079.webp
  const FRAME_FPS    = 20;
  const FRAME_PREFIX = 'frame_';
  const FRAME_PAD    = 3;    // zero-padded to 3 digits

  const DETECT_TIMEOUT_MS = 2500; // safety net only — normal case resolves via timeupdate around 0.35s, this just guards against a stalled/broken load

  // First frame of the clip, inlined as base64 — this is what paints
  // the instant this script runs, with zero network round-trip, so
  // there is nothing for the hero section to flash into before it.
  const FIRST_FRAME_DATA_URI = 'data:image/webp;base64,';

  function frameSrc(i) {
    return FRAME_DIR + FRAME_PREFIX + String(i).padStart(FRAME_PAD, '0') + '.webp';
  }

  // ── Overlay shell — created and painted SYNCHRONOUSLY, before any
  // async work (video probing, frame preloading) begins. This is the
  // fix: nothing about showing *something* over the hero waits on
  // network or detection logic anymore. ──────────────────────────
  const overlay = document.createElement('div');
  overlay.id = 'lumina-loader';
  Object.assign(overlay.style, {
    position: 'fixed', inset: '0',
    zIndex: '99999',
    overflow: 'hidden',
    cursor: 'default',
    backgroundImage: `url(${FIRST_FRAME_DATA_URI})`,
    backgroundSize: 'cover',
    backgroundPosition: 'center',
    backgroundRepeat: 'no-repeat',
  });
  // Confirmed via your script tag position (end of <body>) that body
  // always exists by the time this runs — appending there directly,
  // not to documentElement, so the overlay is a normal child of <body>
  // and participates in the page's regular stacking/rendering context
  // like everything else, instead of sitting as a sibling of it.
  document.body.appendChild(overlay);
  document.body.style.overflow = 'hidden';

  let skipped = false;
  function skip() {
    if (skipped) return;
    skipped = true;
    cleanup();
  }

  let cleanupFns = [];
  function cleanup() {
    cleanupFns.forEach(fn => { try { fn(); } catch (e) {} });
    overlay.remove();
    document.body.style.overflow = '';
  }

  overlay.addEventListener('click', skip);
  overlay.addEventListener('touchend', skip, { passive: true });

  // ── Play immediately, verify alpha support on the SAME live element ──
  // Previous version ran a full hidden detection test on a throwaway
  // video, then created a SECOND fresh video for real playback once
  // detection resolved — paying for two full video loads back-to-back
  // before anything visible happened. That redundant second load was
  // the actual source of the ~2s startup delay. Fixed by using one
  // video for both: it plays visibly from the first instant, and the
  // alpha check runs against that same live, already-playing element.
  // If this browser turns out not to genuinely support it (Firefox/
  // Safari — a minority of traffic), we swap to the frame-sequence
  // fallback at that point; the common case (Chrome/Edge) never pays
  // any detection overhead at all.
  function initVideoWithLiveDetection() {
    const video = document.createElement('video');
    video.muted = true;
    video.playsInline = true;
    video.autoplay = true;
    video.preload = 'auto';
    Object.assign(video.style, {
      position: 'absolute', inset: '0',
      width: '100%', height: '100%',
      objectFit: 'cover',
    });
    video.src = WEBM_SRC;

    // Clear the inline placeholder now — video is going up immediately.
    overlay.style.backgroundImage = 'none';
    overlay.appendChild(video);
    document.body.style.overflow = 'hidden';

    let settledSupport = false;
    let swappedToFallback = false;


    video.addEventListener('error', () => {
      console.warn('[lumina-loader] WebM failed to load at', WEBM_SRC, '— falling back to WebP frame sequence.');
      if (!settledSupport) { settledSupport = true; swapToFallback(); }
    });

    const SAMPLE_AT = 0.35; // seconds — early enough to keep any fallback-case glitch brief
    const detectTimeout = setTimeout(() => {
      if (settledSupport) return;
      settledSupport = true;
      console.warn('[lumina-loader] Alpha-detection never resolved after', DETECT_TIMEOUT_MS, 'ms — falling back to WebP frame sequence.');
      swapToFallback();
    }, DETECT_TIMEOUT_MS);

    video.addEventListener('timeupdate', function onTimeUpdate() {
      if (settledSupport || video.currentTime < SAMPLE_AT) return;
      settledSupport = true;
      video.removeEventListener('timeupdate', onTimeUpdate);
      clearTimeout(detectTimeout);
      try {
        const c = document.createElement('canvas');
        c.width = video.videoWidth || 100;
        c.height = video.videoHeight || 100;
        const cx = c.getContext('2d');
        cx.drawImage(video, 0, 0, c.width, c.height);
        const alpha = cx.getImageData(Math.floor(c.width / 2), Math.floor(c.height / 2), 1, 1).data[3];
        if (alpha >= 220) swapToFallback();
        // else: alpha confirmed, this same video just keeps playing — no swap, no extra load.
      } catch (e) {
        console.warn('[lumina-loader] Alpha-detection canvas read failed:', e.message, '— falling back to WebP frame sequence.');
        swapToFallback();
      }
    });

    function swapToFallback() {
      if (swappedToFallback) return;
      swappedToFallback = true;
      video.pause();
      video.remove();
      initFrameSequence();
    }

    video.addEventListener('ended', () => {
      if (swappedToFallback) return; // fallback already took over
      if (!skipped) cleanup();
    });

    video.play().catch((e) => {
      console.warn('[lumina-loader] video.play() was rejected:', e.message, '— falling back to WebP frame sequence.');
      if (!settledSupport) { settledSupport = true; swapToFallback(); }
    });

    cleanupFns.push(() => { video.pause(); video.remove(); });
  }

  // ── Path B: WebP frame-sequence, drawn on canvas ───────────────
  function initFrameSequence() {
    let loadedCount = 0;
    let failedCount = 0;
    const images = new Array(FRAME_COUNT);
    let ready = false;

    for (let i = 1; i <= FRAME_COUNT; i++) {
      const img = new Image();
      const src = frameSrc(i);
      img.onload = onFrameReady;
      img.onerror = () => {
        failedCount++;
        if (failedCount <= 3) { // don't spam the console for every one of 79 frames
          console.warn('[lumina-loader] Frame failed to load:', src);
        }
        onFrameReady();
      };
      img.src = src;
      images[i - 1] = img;
    }

    function onFrameReady() {
      loadedCount++;
      if (loadedCount === FRAME_COUNT && !ready) {
        ready = true;
        if (failedCount > 0) {
          console.warn(
            '[lumina-loader]', failedCount, 'of', FRAME_COUNT,
            'frames failed to load. Check that Assets/images/loader-frames/ contains frame_001.webp through frame_' +
            String(FRAME_COUNT).padStart(FRAME_PAD, '0') + '.webp directly (not nested in a subfolder).'
          );
        }
        if (failedCount === FRAME_COUNT) {
          console.error('[lumina-loader] ALL frames failed to load — nothing will render. Falling back to an immediate cleanup instead of holding on a blank/frozen overlay.');
          cleanup();
          return;
        }
        startPlayback();
      }
    }

    function startPlayback() {
      const canvas = document.createElement('canvas');
      Object.assign(canvas.style, { display: 'block', width: '100%', height: '100%' });

      // Same fix as the native video path — clear the placeholder now
      // that the canvas is about to take over drawing real frames.
      overlay.style.backgroundImage = 'none';

      overlay.appendChild(canvas);
      document.body.style.overflow = 'hidden';

      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      const ctx = canvas.getContext('2d');
      function resize() {
        canvas.width  = window.innerWidth  * dpr;
        canvas.height = window.innerHeight * dpr;
        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      }
      resize();
      window.addEventListener('resize', resize, { passive: true });
      cleanupFns.push(() => window.removeEventListener('resize', resize));

      function coverRect(srcW, srcH, destW, destH) {
        const srcRatio = srcW / srcH;
        const destRatio = destW / destH;
        let sx, sy, sw, sh;
        if (srcRatio > destRatio) {
          sh = srcH;
          sw = srcH * destRatio;
          sx = (srcW - sw) / 2;
          sy = 0;
        } else {
          sw = srcW;
          sh = srcW / destRatio;
          sx = 0;
          sy = (srcH - sh) / 2;
        }
        return { sx, sy, sw, sh };
      }

      const totalDuration = FRAME_COUNT / FRAME_FPS;
      const startTime = performance.now();
      let raf;

      function loop(now) {
        const elapsed = (now - startTime) / 1000;
        if (elapsed >= totalDuration) {
          cleanup();
          return;
        }

        const frameIndex = Math.min(FRAME_COUNT - 1, Math.floor(elapsed * FRAME_FPS));
        const img = images[frameIndex];

        const W = window.innerWidth, H = window.innerHeight;
        ctx.clearRect(0, 0, W, H);
        if (img && img.naturalWidth) {
          const r = coverRect(img.naturalWidth, img.naturalHeight, W, H);
          ctx.drawImage(img, r.sx, r.sy, r.sw, r.sh, 0, 0, W, H);
        } else if (frameIndex === 0) {
          console.error('[lumina-loader] First frame has no naturalWidth — image never actually decoded despite onload firing. img.src:', img ? img.src : 'undefined');
        }

        raf = requestAnimationFrame(loop);
      }

      cleanupFns.push(() => cancelAnimationFrame(raf));
      raf = requestAnimationFrame(loop);
    }
  }

  // ── Kick off ─────────────────────────────────────────────────
  initVideoWithLiveDetection();
})();
